// Read-only observer. The original page owns all gameplay and save operations.
const frame=document.getElementById('baseline-frame'),gaps=[];let last=0,request=0;
function sample(now){if(last&&now-last<500){gaps.push(now-last);if(gaps.length>120)gaps.shift();}last=now;request=requestAnimationFrame(sample);}
function snapshot(){const p=frame.contentWindow?.performance,entries=p?.getEntriesByType('resource')||[],nav=p?.getEntriesByType('navigation')[0],paint=p?.getEntriesByType('paint')||[],sorted=[...gaps].sort((a,b)=>a-b);return {version:1,engine:'original DOM/SVG/pixel map',recordedAt:new Date().toISOString(),loadEventEndMs:nav?.loadEventEnd||null,domContentLoadedMs:nav?.domContentLoadedEventEnd||null,firstContentfulPaintMs:paint.find(e=>e.name==='first-contentful-paint')?.startTime??null,rafIntervalP50Ms:sorted[Math.floor(sorted.length*.5)]??null,drawCalls:null,drawCallsNote:'Not applicable to DOM; RAF cadence is not measured paint FPS',jsHeapBytes:performance.memory?.usedJSHeapSize??null,jsHeapNote:'May include wrapper and shared process; not GPU bytes',resourceEntries:entries.length,encodedResourceBytes:entries.reduce((s,e)=>s+e.encodedBodySize,0),transferBytes:entries.reduce((s,e)=>s+e.transferSize,0),viewport:{width:frame.clientWidth,height:frame.clientHeight},note:'Manual local observation only; original feature saves work normally.'};}
frame.addEventListener('load',()=>{frame.contentWindow.performance.setResourceTimingBufferSize(2000);document.getElementById('baseline-status').textContent='已載入，請停留灣區 10 秒後匯出。';});
document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(request);request=0;last=0;if(!document.hidden)request=requestAnimationFrame(sample);});request=requestAnimationFrame(sample);
window.addEventListener('pagehide',()=>cancelAnimationFrame(request));
document.getElementById('export-baseline').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='nba-island-2d-baseline.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),0);});
